def convert_legacy_inventory_states(apps, schema_editor):
    Stock = apps.get_model('inventory', 'Stock')
    TransferRequest = apps.get_model('inventory', 'TransferRequest')
    Order = apps.get_model('orders', 'Order')

    # Old checkout deducted on-hand immediately. Restore physical on-hand
    # and represent still-open commitments as reservations.
    open_orders = Order.objects.filter(
        models.Q(status='PENDING', payment_method='MPESA_STK')
        | models.Q(
            payment_method='COD',
            status__in=['PROCESSING', 'PACKED', 'READY_FOR_PICKUP'],
        ),
    ).exclude(order_type='WALK_IN').prefetch_related('items')
    for order in open_orders:
        for item in order.items.all():
            lookup = {'branch_id': order.branch_id}
            if item.variant_id:
                lookup.update(variant_id=item.variant_id, product_id=None)
            else:
                lookup.update(product_id=item.product_id, variant_id=None)
            Stock.objects.filter(**lookup).update(
                quantity=models.F('quantity') + item.quantity,
                reserved_quantity=models.F('reserved_quantity') + item.quantity,
            )

    TransferRequest.objects.filter(status='CONFIRMED').update(status='RECEIVED')


